      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Is algo trading legal for retail traders in India?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Yes, through compliant channels — broker-provided APIs and approved algo products under SEBI's evolving framework. Unregulated third-party algo services making return promises should be avoided.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Do I need to know coding for algo trading?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"For custom strategies, yes — Python is the standard. Non-coders can use strategy marketplaces and no-code platforms, but should understand enough to evaluate what they're deploying.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How much capital do I need for algo trading?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Beyond trading capital, budget for data/API fees and infrastructure. Start small: automate one proven manual strategy with modest size before scaling anything.\"\n      }\n    }\n  ]\n}",
