      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Do candlestick patterns really work?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"They work as probabilistic signals in context — at key levels, with trend alignment — not as standalone predictions. Backtest any pattern in your market and timeframe before trusting it with capital.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Which candlestick pattern is most reliable?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Engulfing patterns at major support/resistance zones have among the best reputations, but 'most reliable' depends on market, timeframe and how you define the setup. Reliability comes from the full setup, not the candle alone.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Do candlestick patterns work on intraday charts?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Less reliably — lower timeframes contain more noise and false signals. Patterns gain significance on hourly charts and above, with daily charts the sweet spot for most traders.\"\n      }\n    }\n  ]\n}",
