      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Article\",\n  \"headline\": \"Crypto Tax in India: The 30% Rule and 1% TDS Explained (2026)\",\n  \"description\": \"India's crypto tax explained: 30% tax on virtual digital asset gains, 1% TDS, no loss set-off — what traders must know in 2026. Not tax advice.\",\n  \"datePublished\": \"2026-09-24\",\n  \"author\": {\n    \"@type\": \"Organization\",\n    \"name\": \"Trading Expo India\"\n  }\n}",
