      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How many stocks should a diversified trader hold?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Count risk drivers, not tickers. Five positions across uncorrelated drivers diversify better than twenty stocks in two sectors. For most traders, 4–8 genuinely different exposures is a practical range.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Does diversification reduce returns?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"It reduces volatility and tail risk; it can modestly reduce peak returns in raging bull markets. The trade is intentional: smoother compounding and survival through regimes that destroy concentrated books.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Can I diversify with Indian currency derivatives?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Yes — USD–INR and other INR pairs respond to macro drivers (RBI policy, crude, global dollar) that differ from equity drivers, making them a useful diversification leg. See our USD–INR guide.\"\n      }\n    }\n  ]\n}",
      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"BreadcrumbList\",\n  \"itemListElement\": [\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 1,\n      \"name\": \"Home\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 2,\n      \"name\": \"Blog\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog.html\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 3,\n      \"name\": \"Diversifying a Trading Portfolio: Beyond 'Don't Put All Eggs in One Basket'\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog/diversifying-trading-portfolio.html\"\n    }\n  ]\n}"
