      "{\"@context\": \"https://schema.org\", \"@type\": \"BreadcrumbList\", \"itemListElement\": [{\"@type\": \"ListItem\", \"position\": 1, \"name\": \"Home\", \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/\"}, {\"@type\": \"ListItem\", \"position\": 2, \"name\": \"Blog\", \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog.html\"}, {\"@type\": \"ListItem\", \"position\": 3, \"name\": \"India's Trading Boom in Numbers — Trading Expo India 2027\", \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog/india-trading-community-by-the-numbers.html\"}]}"
