      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"I'm introverted — can I still network at expos?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Yes. Prepare your intro, use situational openers, aim for a few deep conversations rather than working the room, and remember everyone is there to talk about the same passion — markets.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What should I say when approaching someone?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Be specific and curious: reference the session you both attended, ask what they're working on, or ask which exhibitors impressed them. Avoid pitching in the first two minutes.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How do I follow up without being awkward?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Reference something specific from your conversation, keep it short, and offer value (an article, an introduction) before asking for anything. A 48-hour window keeps the connection fresh.\"\n      }\n    }\n  ]\n}",
      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"BreadcrumbList\",\n  \"itemListElement\": [\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 1,\n      \"name\": \"Home\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 2,\n      \"name\": \"Blog\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog.html\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 3,\n      \"name\": \"Networking at Trading Events: How to Build Relationships That Matter\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog/networking-tips-trading-events.html\"\n    }\n  ]\n}"
