      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"BreadcrumbList\",\n  \"itemListElement\": [\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 1,\n      \"name\": \"Home\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 2,\n      \"name\": \"Blog\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog.html\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 3,\n      \"name\": \"SEBI's 2026 F&O Verdict: 87.7% of Retail Traders Lost Money \\u2014 What It Means for You\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog/sebi-fo-study-2026-retail-losses.html\"\n    }\n  ]\n}"
