      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"BreadcrumbList\",\n  \"itemListElement\": [\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 1,\n      \"name\": \"Home\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 2,\n      \"name\": \"Blog\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog.html\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 3,\n      \"name\": \"Swing Trading Strategy for Indian Markets: Capturing Multi-Day Moves\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog/swing-trading-strategy-india.html\"\n    }\n  ]\n}"
