      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Article\",\n  \"headline\": \"Trading Expo India 2027 Awards: Celebrating Excellence in Trading & Fintech\",\n  \"description\": \"Trading Expo India 2027 Awards: celebrating excellence across brokers, fintech, educators and platforms — categories, spirit and how winners are honoured.\",\n  \"datePublished\": \"2026-09-24\",\n  \"author\": {\n    \"@type\": \"Organization\",\n    \"name\": \"Trading Expo India\"\n  }\n}",
      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What are the Trading Expo India 2027 Awards?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"An awards programme during the expo honouring excellence across trading platforms, brokers, fintech innovation, education and community contribution. Categories and nominations will be announced via official expo channels.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How are award winners chosen?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Details of categories, nominations and judging will be published through official Trading Expo India announcements as the event approaches. Follow the official website for verified information.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Can companies nominate themselves for awards?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Nomination mechanics will be announced officially. Companies interested should exhibit or engage with the expo and monitor official channels for the nomination process.\"\n      }\n    }\n  ]\n}",
