      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"Article\",\n  \"headline\": \"Trading Glossary: 40 Essential Terms Every Beginner Must Know\",\n  \"description\": \"Essential trading glossary: 40 must-know terms from bid-ask spread to short selling, explained in plain English for Indian beginners.\",\n  \"datePublished\": \"2026-09-24\",\n  \"author\": {\n    \"@type\": \"Organization\",\n    \"name\": \"Trading Expo India\"\n  }\n}",
      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What is the bid-ask spread?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"The difference between the highest price buyers will pay (bid) and the lowest price sellers will accept (ask). It is effectively a cost of trading — narrower spreads in liquid instruments mean cheaper trading.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What does R-multiple mean?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"Your profit or loss expressed in units of the risk you took. Risking ₹5,000 to make ₹10,000 is +2R; losing ₹5,000 is −1R. Professionals evaluate strategies in R, not rupees.\"\n      }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"What is slippage?\",\n      \"acceptedAnswer\": {\n        \"@type\": \"Answer\",\n        \"text\": \"The difference between the price you expected when placing an order and the price you actually got — common in fast markets and illiquid instruments, and a real cost most beginners underestimate.\"\n      }\n    }\n  ]\n}",
