      "{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"BreadcrumbList\",\n  \"itemListElement\": [\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 1,\n      \"name\": \"Home\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 2,\n      \"name\": \"Blog\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog.html\"\n    },\n    {\n      \"@type\": \"ListItem\",\n      \"position\": 3,\n      \"name\": \"Trading Psychology: Mastering Fear, Greed and Revenge Trading\",\n      \"item\": \"https://dawoodshah2232-svg.github.io/tradingexpo-india/blog/trading-psychology-master-emotions.html\"\n    }\n  ]\n}"
